local config = {
  ui_story_31550401_1_dialog_content = "\"Bilah pedangku berkilau jernih dan terang, bagaikan cahaya bulan yang mengoyak kegelapan.\"",
  ui_story_31550401_2_dialog_content = "\"Kini ia tumpul oleh kemarahan dan tercoreng oleh kebingungan.\"",
  ui_story_31550401_3_dialog_content = "\"Ia menderita, tak berdaya, kesepian, dan marah.\"",
  ui_story_31550401_4_dialog_content = "\"Ia memanggilku dengan suara yang dipenuhi haus darah, mendambakan aku menjadi raja.\"",
  ui_story_31550401_5_dialog_content = "Barton tampaknya... sedikit aneh akhir-akhir ini.",
  ui_story_31550401_6_dialog_content = "Apa yang dia inginkan dariku?",
  ui_story_31550401_7_dialog_content = "Heh, heh...",
  ui_story_31550401_8_dialog_content = "Anda di sini!",
  ui_story_31550401_9_dialog_content = "Tapi, kau terlalu lambat sekali!",
  ui_story_31550401_10_dialog_content = "Tidak peduli apa yang sedang kamu lakukan, kamu harus berlari secepat mungkin ke titik kumpul setelah mendengar panggilan berkumpul!",
  ui_story_31550401_11_dialog_content = "Kamu dengar itu, Makhluk Lemah?",
  ui_story_31550401_12_dialog_content = "Ya, Legion Commander!",
  ui_story_31550401_13_dialog_content = "Tunggu sebentar... Kami hanya sedang mengobrol lewat terminal, ini bukan panggilan berkumpul!",
  ui_story_31550401_14_dialog_content = "Kau benar.",
  ui_story_31550401_15_dialog_content = "Kalau begitu, ganti suara Firefly dengan suara trompet Illumina.",
  ui_story_31550401_16_dialog_content = "Tiupkan trompet setiap hari untuk memastikan semua orang mematuhi aturan di barak ini dengan ketat!",
  ui_story_31550401_17_option_content = "Maafkan aku, tapi aku menolak!",
  ui_story_31550401_18_dialog_content = "Tolong, jangan lakukan itu! Ini adalah Colossus, bukan barak!",
  ui_story_31550401_19_dialog_content = "Seingatku, aku juga bukan prajurit Illumina!",
  ui_story_31550401_20_option_content = "Begini...",
  ui_story_31550401_21_dialog_content = "Jika aku benar-benar mengubahnya... Aku akan terbangun oleh suara trompet setiap hari.",
  ui_story_31550401_22_dialog_content = "Ini pasti akan merusak suasana hatiku sepanjang hari!",
  ui_story_31550401_23_dialog_content = "Absolut tidak! Tolong, menjauhlah dari Firefly!",
  ui_story_31550401_24_dialog_content = "Heheh... Aku lihat, kau masih pandai berargumen seperti biasanya, ya, Caelestite lemah.",
  ui_story_31550401_25_dialog_content = "Tidak mungkin... Lupakan saja. Aku hanya akan menganggapnya sebagai pujian.",
  ui_story_31550401_26_dialog_content = "Bagus sekali. Aku memang mengagumi ketenanganmu.",
  ui_story_31550401_27_dialog_content = "Cukup berbasa-basi. Bagaimana kalau satu putaran perang-perangan?",
  ui_story_31550401_28_dialog_content = "...",
  ui_story_31550401_29_dialog_content = "(Aku tidak akan semudah itu kalah! Tidak kali ini!)",
  ui_story_31550401_30_dialog_content = "(Aku bahkan telah diam-diam berlatih keras untuk waktu yang lama... dan bahkan meminta bantuan dari Carleen dan yang lainnya...)",
  ui_story_31550401_31_dialog_content = "(Biarkan aku melihat, Barton! Bagaimana kamu akan melawan ini?!)",
  ui_story_31550401_32_dialog_content = "<color=#e8d9bb>Klak</color>",
  ui_story_31550401_33_dialog_content = "Menarik, tapi itu tidak berguna!",
  ui_story_31550401_34_dialog_content = "<color=#e8d9bb>Klak</color>",
  ui_story_31550401_35_dialog_content = "Apa?! Penataan sempurnaku hancur begitu cepat!",
  ui_story_31550401_36_dialog_content = "Hmph, ini hanyalah trik yang telah kau pelajari dari pemain catur Lumopolis.",
  ui_story_31550401_37_dialog_content = "Meskipun tampak sempurna di permukaan, ini penuh dengan kekurangan.",
  ui_story_31550401_38_dialog_content = "Yang perlu aku lakukan hanyalah menyesatkanmu sedikit, dan kamu langsung jatuh ke dalam perangkapku.",
  ui_story_31550401_39_dialog_content = "Kamu masih jauh terlalu tidak berpengalaman untuk menggunakan trik seperti ini pada pemain catur berpengalaman!",
  ui_story_31550401_40_dialog_content = "Ayo, buat gerakanmu!",
  ui_story_31550401_41_dialog_content = "Rajamu akan jatuh dalam tiga langkah!",
  ui_story_31550401_42_dialog_content = "A-Aku tidak akan pernah mengaku kalah!",
  ui_story_31550401_43_dialog_content = "<color=#e8d9bb>Klak</color>",
  ui_story_31550401_44_dialog_content = "Maaf... Aku telah kalah.",
  ui_story_31550401_45_dialog_content = "Tapi, ini belum berakhir! Ayo main ronde lainnya!",
  ui_story_31550401_46_dialog_content = "Hahaha, kamu punya beberapa nyali!",
  ui_story_31550401_47_dialog_content = "(Tidak... Serangan Barton sangat cepat dan agresif. Dia tidak memberiku kesempatan untuk mengambil nafas dan berpikir.)",
  ui_story_31550401_48_dialog_content = "(Dia tampak lebih kuat dari sebelumnya. Apakah mungkin Chord Link telah meningkatkan pikirannya?!)",
  ui_story_31550401_49_dialog_content = "(Semua yang bisa aku lakukan sekarang adalah memanfaatkan peluang dan melihat bagaimana kelanjutannya dari sini...)",
  ui_story_31550401_50_dialog_content = "<color=#e8d9bb>Klak</color>",
  ui_story_31550401_51_dialog_content = "...",
  ui_story_31550401_52_dialog_content = "<color=#e8d9bb>Klak</color>",
  ui_story_31550401_53_dialog_content = "…!",
  ui_story_31550401_54_dialog_content = "Hah?",
  ui_story_31550401_55_dialog_content = "(Saya sebenarnya telah menemukan celah! Dalam hal ini, saya tidak akan menahan diri!)",
  ui_story_31550401_56_dialog_content = "12 kalah, 0 menang, dan 1 seri...",
  ui_story_31550401_57_dialog_content = "Hahaha! Lumayan juga, Makhluk Lemah.",
  ui_story_31550401_58_dialog_content = "Setidaknya, kau berhasil bermain seri dalam satu pertandingan. Kau menjadi lebih baik dengan sangat cepat!",
  ui_story_31550401_59_dialog_content = "Seri itu... Hanya karena kau telah membuat kesalahan, 'kan?",
  ui_story_31550401_60_dialog_content = "Jujur saja... Kau membuatku merasa takut saat kita bermain catur tadi.",
  ui_story_31550401_61_dialog_content = "Seakan... Aku bisa merasakan niatmu untuk membunuhku selama permainan.",
  ui_story_31550401_62_dialog_content = "Hmph... Caelestite memang peka, bukan?",
  ui_story_31550401_63_dialog_content = "Aku memang menyerah pada dorongan bodoh dan membuat langkah yang salah.",
  ui_story_31550401_64_dialog_content = "Aku akan mengakui bahwa aku juga percaya ada beberapa masalah dalam diriku sendiri.",
  ui_story_31550401_65_dialog_content = "Meskipun perangkat bodoh itu telah meningkatkan kekuatanku, sepertinya juga telah mengambil sesuatu dariku.",
  ui_story_31550401_66_dialog_content = "Bahkan ada kalanya kesadaranku berantakan, sama seperti saat aku membuat kesalahan dasar tadi.",
  ui_story_31550401_67_dialog_content = "Lebih jauh lagi, kemarahan dan rasa kesal karena kalah dari orang itu... selalu menjaga api di hatiku tetap menyala.",
  ui_story_31550401_68_dialog_content = "Barton...",
  ui_story_31550401_69_dialog_content = "Jika ini adalah harga yang harus dibayar untuk menjadi lebih kuat, saya bersedia untuk dicabik-cabik.",
  ui_story_31550401_70_dialog_content = "Kamu tahu... Mungkin, ada sesuatu yang bisa aku bantu?",
  ui_story_31550401_71_dialog_content = "Itu tidak perlu. Makhluk lemah kecil, seperti kamu, tidak akan bisa membantu apa-apa.",
  ui_story_31550401_72_dialog_content = "Sebuah pion tidak akan pernah bisa naik ke takhta hanya dengan mengandalkan kekuatan eksternal saja.",
  ui_story_31550401_73_dialog_content = "Saya menghargai pemikiran itu, tapi saya akan menemukan sesuatu sendiri. Ayo pergi, Sergeant.",
  ui_story_31550401_74_dialog_content = "*Meraung*",
  ui_story_31550401_75_dialog_content = "Tunggu saja sampai kau lihat Legion Commander yang tak terukur kehebatannya!",
  ui_story_31550401_76_dialog_content = "Hahahahaha!",
  ui_story_31550401_77_dialog_content = "Hmm? Kapan kedua anjing itu sampai di sini? Tunggu, apakah dia baru saja pergi dengan anjing-anjing itu?",
  ui_story_31550401_78_dialog_content = "Aku hanya tidak bisa tidak merasa khawatir...",
  ui_story_31550401_79_dialog_content = "Kita sampai, Sergeant.",
  ui_story_31550401_80_dialog_content = "Auuu!",
  ui_story_31550401_81_dialog_content = "Seharusnya kau masih ingat tempat ini karena di sinilah aku menaikkan pangkatmu menjadi Sergeant.",
  ui_story_31550401_82_dialog_content = "Ooowooooooooo!",
  ui_story_31550401_83_dialog_content = "Tidak buruk! Itu gonggongan yang bagus dan jelas!",
  ui_story_31550401_84_dialog_content = "Sekarang kapal kecil itu telah tenggelam, aku akan mengakhiri ini sendirian, dengan kalian berdua sebagai saksi-saksiku!",
  ui_story_31550401_85_dialog_content = "Auuu!",
  ui_story_31550401_86_dialog_content = "Untuk menghadapi laut yang mengerikan ini sekali lagi...",
  ui_story_31550401_87_dialog_content = "Air laut yang menusuk dingin...",
  ui_story_31550401_88_dialog_content = "Seolah-olah itu mencoba merobek kulitku dan menyerang tubuhku...",
  ui_story_31550401_89_dialog_content = "Tingkat air telah mencapai dadaku... Semakin sulit untuk menggerakkan anggota tubuhku dan bernapas.",
  ui_story_31550401_90_dialog_content = "Sepertinya laut mencoba menahan aku... atau memelukku.",
  ui_story_31550401_91_dialog_content = "Sama seperti kekuatan baru itu... dan rasa kesal yang meluap-luap yang datang dengan gemuruh.",
  ui_story_31550401_92_dialog_content = "Aku, Barton... tak akan pernah kalah darimu.",
  ui_story_31550401_93_dialog_content = "Ya... Itu dia. Gunakan seluruh tubuhmu untuk merangkul kekuatan... serta rasa takut.",
  ui_story_31550401_94_dialog_content = "...",
  ui_story_31550401_95_dialog_content = "…!",
  ui_story_31550401_96_dialog_content = "Sialan... Aku gagal.",
  ui_story_31550401_97_dialog_content = "Akan sia-sia meledakkan laut menjadi berkeping-keping... karena airnya hanya akan bersatu kembali ke laut.",
  ui_story_31550401_98_dialog_content = "... Aku akan beristirahat dulu, jadi tolong berjaga-jaga atas diriku, Sergeant.",
  ui_story_31550401_99_dialog_content = "Auuu!",
  ui_story_31550401_100_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_101_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_102_dialog_content = "\"Aku memang telah mengalami beberapa perubahan.\"",
  ui_story_31550401_103_dialog_content = "\"Tapi, aku tahu ada hal yang tidak bisa diubah...\"",
  ui_story_31550401_104_dialog_content = "Barton...",
  ui_story_31550401_105_dialog_content = "Barton... Kenapa kau ragu?",
  ui_story_31550401_106_dialog_content = "O-Officer Pango?!",
  ui_story_31550401_107_dialog_content = "Kenapa kau di sini!? Bukankah kau...",
  ui_story_31550401_108_dialog_content = "Apa yang coba kamu katakan? Astaga, lihatlah wajahmu yang tidak sedap dipandang itu!",
  ui_story_31550401_109_dialog_content = "Dan kau menyebut dirimu seorang prajurit?",
  ui_story_31550401_110_dialog_content = "Maaf, Pak... Tapi, aku...",
  ui_story_31550401_111_dialog_content = "Tanpa alasan atau tapi! Kamu harus benar-benar ingat siapa dirimu!",
  ui_story_31550401_112_dialog_content = "Izinkan aku bertanya ini: Apakah kamu masih ingat di mana letak kesetiaanmu?",
  ui_story_31550401_113_dialog_content = "Tentu saja, aku pedang dan perisai Illumina!",
  ui_story_31550401_114_dialog_content = "Bagus. Lalu, apa arti kejayaan bagi kamu?",
  ui_story_31550401_115_dialog_content = "Suatu kehormatan bagi kami untuk mengusir para Eclipsite dan melindungi semua Aurorian!",
  ui_story_31550401_116_dialog_content = "Luar biasa! Apa yang kauperjuangkan?",
  ui_story_31550401_117_dialog_content = "Jayalah Illumina!",
  ui_story_31550401_118_dialog_content = "Bicaralah, aku tak bisa mendengarmu!!",
  ui_story_31550401_119_dialog_content = "Jayalah Illumina!!!",
  ui_story_31550401_120_dialog_content = "Bagus sekali!!",
  ui_story_31550401_121_dialog_content = "Bukankah kamu sudah tahu ini?",
  ui_story_31550401_122_dialog_content = "Kau ini seorang petarung, seorang prajurit!",
  ui_story_31550401_123_dialog_content = "Kamu dikelilingi oleh tak terhitung kawan-kawan seperjuangan yang memiliki minat dan keyakinan yang sama!",
  ui_story_31550401_124_dialog_content = "Namun, bukan hanya kamu yang sekarang takut akan kekuatan yang menakutkan itu, tapi kamu juga takut kehilangan kendali atasnya dan membahayakan mereka?",
  ui_story_31550401_125_dialog_content = "Ya…",
  ui_story_31550401_126_dialog_content = "Itu tidak masuk akal! Tolong perhatiannya!",
  ui_story_31550401_127_dialog_content = "Siap, Pak!",
  ui_story_31550401_128_dialog_content = "Menurutmu hanya kau yang bisa jadi raja, Little Barton?",
  ui_story_31550401_129_dialog_content = "Datanglah, Prajurit, ceritakan padaku bagaimana seseorang bisa menjadi raja?",
  ui_story_31550401_130_dialog_content = "Dengan tekad yang tidak goyah, kamu harus menghabiskan semua darah dan keringatmu untuk mengumpulkan kekuatan yang cukup!",
  ui_story_31550401_131_dialog_content = "Benar sekali! Jika kau mampu menjadi raja, kawan-kawan seperjuanganmu juga akan memiliki kekuatan yang sama!",
  ui_story_31550401_132_dialog_content = "Bahkan jika kau kehilangan kendali dan menjadi \"raja gila\", mereka masih memiliki kekuatan untuk membawamu ke jalan yang benar!",
  ui_story_31550401_133_dialog_content = "Siap, Pak!",
  ui_story_31550401_134_dialog_content = "Masukkan ini ke dalam pikiranmu...",
  ui_story_31550401_135_dialog_content = "Jangan pernah mengecewakan kawan-kawanmu, apalagi meremehkan mereka!",
  ui_story_31550401_136_dialog_content = "Siap, Pak!!",
  ui_story_31550401_137_dialog_content = "Baiklah, lanjutkan. Terima kekuatanmu yang akan membuka jalan baru.",
  ui_story_31550401_138_dialog_content = "Jangan biarkan darah kita menetes sia-sia!",
  ui_story_31550401_139_dialog_content = "Itu perintah!",
  ui_story_31550401_140_dialog_content = "Ya, Petugas Pango!!",
  ui_story_31550401_141_dialog_content = "Wah!!",
  ui_story_31550401_142_dialog_content = "Awoo!!",
  ui_story_31550401_143_dialog_content = "Dia akhirnya bangun. Bukankah sudah kubilang dia akan baik-baik saja?",
  ui_story_31550401_144_dialog_content = "Jika Komandan Legion yang mengagumkan Barton tenggelam dalam alam liar seperti ini,",
  ui_story_31550401_145_dialog_content = "Illumina pasti akan jatuh dalam aib, seperti Lumopolis.",
  ui_story_31550401_146_dialog_content = "Kau baik-baik saja, Barton?",
  ui_story_31550401_147_dialog_content = "Ya, aku baik-baik saja... Mengapa semua orang di sini?",
  ui_story_31550401_148_dialog_content = "Nah... Bukankah kamu di sini untuk belajar berenang?",
  ui_story_31550401_149_dialog_content = "Semua orang cukup khawatir tentangmu setelah menghilang begitu lama tanpa mengatakan apa-apa.",
  ui_story_31550401_150_dialog_content = "Ehem, khawatir apanya... Aku baik-baik saja.",
  ui_story_31550401_151_dialog_content = "Bahkan jika dia tidak bisa belajar berenang, saya yakin dia bisa kembali dengan menggali terowongan atau semacamnya. Maksudku, dia Barton, setelah semua.",
  ui_story_31550401_152_dialog_content = "Hahaha, kamu benar sekali!",
  ui_story_31550401_153_dialog_content = "Karena kita semua ada di sini, tak ada yang boleh pergi hari ini. Ayo, mari kita lakukan sesi latihan berenang bersama!",
  ui_story_31550401_154_dialog_content = "Demi kesiapan menghadapi setiap kemungkinan musuh dari laut...",
  ui_story_31550401_155_dialog_content = "Kami, Legion Commander, harus memimpin dalam belajar berenang dengan benar!",
  ui_story_31550401_156_dialog_content = "Itu menarik. Ayo, mari kita lihat siapa yang terbaik.",
  ui_story_31550401_157_dialog_content = "Eh? Tapi, aku tidak membawa baju renang...",
  ui_story_31550401_158_dialog_content = "Ayo. Sudah lama sekali sejak terakhir kali saya mencoba olahraga air.",
  ui_story_31550401_159_dialog_content = "Mereka hanya... berlari untuk berenang begitu saja...",
  ui_story_31550401_160_dialog_content = "Pokoknya, yang terpenting adalah Barton baik-baik saja dan terlihat jauh lebih berenergi sekarang.",
  ui_story_31550401_161_dialog_content = "Namun, saya bertanya-tanya siapa \"Officer Pango\" yang dia terus serukan dalam tidurnya...",
  ui_story_31550401_162_dialog_content = "Namanya terdengar cukup familier, meskipun...",
  ui_story_31550601_1_dialog_content = "Ha, aku tahu kamu akan datang, PlayerName!",
  ui_story_31550601_2_dialog_content = "Hanya karena pesanmu terdengar sangat mendesak, Barton...",
  ui_story_31550601_3_dialog_content = "Itu karena ini mendesak! Komandan lama saya akhirnya bangun lagi!",
  ui_story_31550601_4_dialog_content = "Ini adalah beberapa berita terbaik yang pernah saya dapatkan dalam hidup saya, dan kamu adalah orang pertama yang ingin saya bagikan.",
  ui_story_31550601_5_dialog_content = "Dan, uh... Karena kamu di sini, bisakah kamu menggunakan kekuatanmu untuk memeriksa kondisi mental Officer Pango? Sangat berterima kasih!",
  ui_story_31550601_6_dialog_content = "Jadi, itulah sebabnya kamu memanggilku!",
  ui_story_31550601_7_dialog_content = "Hah? Sekarang aku pikirkan, kamu tidak mengenakan pakaian ini karena—",
  ui_story_31550601_8_dialog_content = "Benar. Aku khawatir commander mungkin tidak mengenali aku, jadi aku mencari nomor lama ini.",
  ui_story_31550601_9_dialog_content = "Dia terkena pukulan hingga koma saat mempertahankan Kota Gannon dari Eclipsites. Pertempuran itu terjadi lebih dari sepuluh tahun lalu.",
  ui_story_31550601_10_dialog_content = "Selama waktu itu, aku telah berubah dari rekrutan punk yang menjengkelkan menjadi commander hebat yang kamu lihat hari ini! Itulah mengapa aku khawatir dia tidak akan mengenali aku segera.",
  ui_story_31550601_11_dialog_content = "Aku ragu. Kau masih Barton, setelah semua.",
  ui_story_31550601_12_dialog_content = "Selama bertahun-tahun, aku telah berusaha keras untuk berbicara dengannya, berharap suatu hari nanti itu akan membangunkannya...",
  ui_story_31550601_13_dialog_content = "Ketika saya tiba-tiba menerima panggilan, saya kehilangan kata-kata.",
  ui_story_31550601_14_dialog_content = "Pokoknya, saya bersyukur kamu datang. Ayo, masuklah.",
  ui_story_31550601_15_dialog_content = "... Berhenti menusuk dan mencolek, sialan! Saya sangat sadar dengan tubuh saya sendiri, terima kasih banyak!",
  ui_story_31550601_16_dialog_content = "Sekarang biarkan aku pergi, kalian idiot! Pertarungannya belum berakhir!",
  ui_story_31550601_17_dialog_content = "Rumah di luar kota?",
  ui_story_31550601_18_dialog_content = "Komandan Barton!",
  ui_story_31550601_19_dialog_content = "Officer Pango... Kamu benar-benar bangun...",
  ui_story_31550601_20_dialog_content = "... Kenapa di dunia ini kamu memakai sesuatu yang tampak begitu bodoh? Tidak apa-apa, kamu datang pada waktunya yang tepat—beritahu mereka untuk membiarkan saya pergi sekarang juga.",
  ui_story_31550601_21_dialog_content = "Mereka menjebakku di sini, mengatakan itu demi kebaikanku atau omong kosong seperti itu.",
  ui_story_31550601_22_dialog_content = "Mereka juga memberitahuku bahwa Darkover Crisis telah berakhir lebih dari sepuluh tahun yang lalu! Bisakah kamu percaya itu?",
  ui_story_31550601_23_dialog_content = "Garis depan dalam bahaya serius. Kota Gannon telah sepenuhnya dikelilingi...",
  ui_story_31550601_24_dialog_content = "Tunggu... Barton... Kapan kamu mulai tumbuh rambut abu-abu?",
  ui_story_31550601_25_dialog_content = "Officer Pango... Pertempuran sudah berakhir lama sekali.",
  ui_story_31550601_26_dialog_content = "... Kamu juga mengeluarkan omong kosong yang sama? Apa yang sebenarnya terjadi di sini?",
  ui_story_31550601_27_dialog_content = "Dan siapa itu rekrutan baru yang tampak lemah itu? Apakah Illumina kembali menurunkan standar pendaftarannya?",
  ui_story_31550601_28_dialog_content = "Halo, Pak. Sebenarnya, saya—",
  ui_story_31550601_29_dialog_content = "Saya perlu kembali ke medan perang, sekarang lakukanlah! Itu perintah, Barton!",
  ui_story_31550601_30_dialog_content = "Aku muak dengan semua perban dan jarum ini! Kirim aku kembali ke garis depan, agar aku bisa mendapatkan udara segar!",
  ui_story_31550601_31_dialog_content = "Saya yakin semuanya akan masuk akal setelah saya kembali ke sana...",
  ui_story_31550601_32_dialog_content = "Siap, Pak!",
  ui_story_31550601_33_dialog_content = "Apa pendapatmu tentang pemulihan Officer Pango, PlayerName? Apakah keadaan mentalnya... normal?",
  ui_story_31550601_34_option_content = "Rasakan Pango",
  ui_story_31550601_35_dialog_content = "Tunggu... Apa ini perasaan ini?",
  ui_story_31550601_36_dialog_content = "Dia benar-benar baik-baik saja... Dia hanya kesulitan mempercayai apa yang orang lain katakan, itu saja.",
  ui_story_31550601_37_dialog_content = "Terima kasih... Ayo pergi, Tuan. Tidak mudah bagi Anda untuk bergerak sekarang, tetapi itulah gunanya kursi roda ini.",
  ui_story_31550601_38_dialog_content = "Apa ini, Barton? Kenapa kamu membawa saya ke museum?",
  ui_story_31550601_39_dialog_content = "Saya yakin mereka sudah menceritakan semua hal kepadamu saat pertama kali bangun, Officer Pango.",
  ui_story_31550601_40_dialog_content = "Kamu terbaring koma selama lebih dari satu dekade. Darkover Crisis juga telah berakhir lama.",
  ui_story_31550601_41_dialog_content = "Seperti yang bisa kamu lihat, bawahanmu yang tak berguna kini menjadi komandan dari 2nd Legion.",
  ui_story_31550601_42_dialog_content = "Ini... Tanda nama anjingku?",
  ui_story_31550601_43_dialog_content = "Benar, Pak. Anda meninggalkan ini padaku bertahun-tahun yang lalu.",
  ui_story_31550601_44_dialog_content = "Apakah kamu masih ingat hari itu? Menuju akhir krisis, kamu menyuruh kita semua untuk mundur, tapi kamu tetap bertahan untuk berjuang.",
  ui_story_31550601_45_dialog_content = "Kita semua sudah aman sekarang, Pak. Semua yang terjadi adalah masa lalu sekarang.",
  ui_story_31550601_46_dialog_content = "Mustahil…",
  ui_story_31550601_47_dialog_content = "Dan sekarang, mari kita arahkan perhatian kita pada upaya berani Divisi Mesin 2nd Legion selama Krisis Darkover.",
  ui_story_31550601_48_dialog_content = "!",
  ui_story_31550601_49_dialog_content = "Seperti yang telah kalian baca sebelumnya, bahkan Kota Gannon jatuh ke tangan serangan Eclipsite pada puncak Krisis Darkover.",
  ui_story_31550601_50_dialog_content = "Untuk memfasilitasi evakuasi kota, setiap anggota dari 2nd Legion tetap tinggal untuk melanjutkan pertempuran melawan musuh.",
  ui_story_31550601_51_dialog_content = "Tank yang kamu lihat di depanmu adalah Model L3 Illumina, dan yang satu ini dioperasikan oleh Legiun ke-2 selama pertempuran itu.",
  ui_story_31550601_52_dialog_content = "Asyik!",
  ui_story_31550601_53_dialog_content = "Itu tank kita, Barton... Apa yang terjadi padanya? Kenapa dia... semua rusak?",
  ui_story_31550601_54_dialog_content = "Karena itu memberikan segalanya untuk menyelamatkan Kota Gannon, Pak, sama seperti Anda.",
  ui_story_31550601_55_dialog_content = "Meski rusak, ia masih belum pensiun. Ia tetap hidup di museum ini untuk mengajar dan menginspirasi generasi mendatang.",
  ui_story_31550601_56_dialog_content = "Tank ini adalah veteran abadi dari Legion 2nd.",
  ui_story_31550601_57_dialog_content = "Komandan Barton? Kami tidak menyangka Anda datang hari ini, pak. Maaf, tapi tamu Anda...",
  ui_story_31550601_58_dialog_content = "Apakah itu... Apakah itu benar-benar kamu? Guardian legendaris dari Central Tower?",
  ui_story_31550601_59_dialog_content = "Ini benar-benar kamu! Akhirnya kamu bangun juga, Komandan Pango!",
  ui_story_31550601_60_dialog_content = "Apa? Dia benar-benar bangun dari komanya?",
  ui_story_31550601_61_dialog_content = "Pango? Kamu maksud komandan legendaris yang memimpin pasukan veteran untuk mempertahankan Central Tower? Di mana?",
  ui_story_31550601_62_dialog_content = "Petugas Pango! Apakah kamu yakin seharusnya bergerak sekarang? Kami ingin berlatih di bawah bimbinganmu, Siap!",
  ui_story_31550601_63_dialog_content = "Hoi! Tunjukkan rasa hormatmu pada Officer, kalian bajingan! Jika kalian ingin bertanya, tanyakan satu per satu!",
  ui_story_31550601_64_dialog_content = "Siap, Pak!",
  ui_story_31550601_65_dialog_content = "Officer Pango! Kamu tidak mengenalku, tapi aku berasal dari Undercity 13 yang baru.",
  ui_story_31550601_66_dialog_content = "Jika bukan karena kamu dan Komandan Wrath, Undercity 13 mungkin sudah rata dengan tanah.",
  ui_story_31550601_67_dialog_content = "Jadi terima kasih... Terima kasih telah menyelamatkan kami, dan memberi kami kesempatan untuk membangun kembali rumah kami.",
  ui_story_31550601_68_dialog_content = "\"Baru\" Undercity 13?",
  ui_story_31550601_69_dialog_content = "Giliran saya! Salam, Officer Pango! Saya lahir dan dibesarkan di salah satu distrik tertua di Kota Gannon.",
  ui_story_31550601_70_dialog_content = "Terima kasih atas keberanianmu, seluruh keluarga saya tetap aman dari Eclipsite.",
  ui_story_31550601_71_dialog_content = "Saya masih anak-anak ketika kita merebut kembali kota, tapi saya mendaftar segera setelah saya cukup umur! Impian saya adalah menjadi pahlawan seperti kamu, pak!",
  ui_story_31550601_72_dialog_content = "\"Merebut kembali kota itu\"...",
  ui_story_31550601_73_dialog_content = "Baiklah, cukup untuk saat ini. Beri ruang untuk petugas.",
  ui_story_31550601_74_dialog_content = "Hmm? Oh, kalau bukan kawan kita yang terhormat, Caelestite! Selamat kembali ke Illumina, temanku.",
  ui_story_31550601_75_dialog_content = "Senang bisa kembali!",
  ui_story_31550601_76_dialog_content = "Kamu seorang Caelestite? Tapi saat Krisis Darkover, Eraveil sudah...",
  ui_story_31550601_77_dialog_content = "... Aku tahu. Sebenarnya, aku—",
  ui_story_31550601_78_dialog_content = "PlayerName cukup beruntung untuk selamat dari serangan di Eraveil! Sesuatu mengatakan padaku bahwa ada banyak Caelestite lain yang menunggunya di luar sana!",
  ui_story_31550601_79_dialog_content = "Banyak hal yang telah membaik sejak Krisis Darkover, pak.",
  ui_story_31550601_80_dialog_content = "Jadi kita benar-benar menang? Apakah Astra benar-benar damai lagi?",
  ui_story_31550601_81_dialog_content = "Ya, pak. Kami menang... Meskipun perdamaian yang kami amankan tidak sempurna, kami berhasil bertahan dari Krisis Darkover.",
  ui_story_31550601_82_dialog_content = "Undercity 13 dibangun kembali, bersama dengan Kota Gannon. Generasi masa depan kita tidak lagi dibesarkan di parit-parit perang.",
  ui_story_31550601_83_dialog_content = "... Aku melihat diriku di cermin saat aku bangun pagi ini.",
  ui_story_31550601_84_dialog_content = "Semua rambut putih di kepala saya... Saya rasa itu bukan dari luka saya sama sekali.",
  ui_story_31550601_85_dialog_content = "Namun, waktu tampaknya juga telah menyembuhkan banyak hal.",
  ui_story_31550601_86_dialog_content = "Meskipun... Aku telah membuang begitu banyak waktu sendiri...",
  ui_story_31550601_87_dialog_content = "Kamu telah menjadi begitu dewasa dalam sekejap mata, Barton.",
  ui_story_31550601_88_dialog_content = "Pelatihanmu lah yang membentuk saya menjadi pilar dari Federasi Illumina, pak.",
  ui_story_31550601_89_dialog_content = "Saya tahu persis apa tugas saya, dan saya memimpin prajurit kita maju tanpa keraguan di hati saya. 2nd Legion berada di tangan yang baik, jadi tolong fokus pada istirahat dan pemulihan, pak.",
  ui_story_31550601_90_dialog_content = "... Heh. Barton yang aku kenal sama sekali tidak akan berbicara seperti itu.",
  ui_story_31550601_91_dialog_content = "Bawa aku untuk melihat monumen, maukah kamu?",
  ui_story_31550601_92_dialog_content = "Siap, Jenderal.",
  ui_story_31550601_93_dialog_content = "Saya juga ingin melihat bagaimana keadaan 2nd Legion sekarang.",
  ui_story_31550601_94_dialog_content = "Harus ada orang yang memastikan kamu tidak mengacaukan segalanya, lagipula.",
  ui_story_31550601_95_dialog_content = "Jika saya mengetahui bahwa Anda hanya mengeluarkan omong kosong barusan, saya akan memberikan Anda pelatihan keras yang sama seperti sebelumnya!",
  ui_story_31550601_96_dialog_content = "Mengerti, Pak!",
  ui_story_31550601_97_dialog_content = "Er, Petugas Pango...",
  ui_story_31550601_98_dialog_content = "Ada apa?",
  ui_story_31550601_99_dialog_content = "Sungguh suatu kehormatan bisa bertemu denganmu, begitu juga dengan Komandan Barton dan Caelestite.",
  ui_story_31550601_100_dialog_content = "Kamu telah berkorban begitu banyak untuk membantu kami, dan untuk membantu seluruh Astra.",
  ui_story_31550601_101_dialog_content = "Bolehkah kita... mengambil foto untuk memperingati hari ini? Tolong?",
  ui_story_31550601_102_dialog_content = "Tentu.",
  ui_story_31550601_103_dialog_content = "Ha! Kemarilah, PlayerName! Kamu tidak selalu mendapatkan kesempatan seperti ini, jadi manfaatkanlah!",
  ui_story_31550601_104_dialog_content = "Foto grup dengan dua pahlawan perang legendaris? Tidak bohong, aku sedikit gugup...",
  ui_story_31550601_105_dialog_content = "Kamu akan bisa melaluinya! Lagipula, kamu juga rekan yang penting dalam perjuangan ini!",
  ui_story_31550601_106_dialog_content = "Semua orang siap? Bagus! Sekarang lihat ke kamera dan ulangi setelah saya—Jayalah Illumina!",
  ui_story_31550601_107_dialog_content = "Jayalah Illumina!",
  ui_story_31550601_108_dialog_content = "Sudah siap! Ayo lihat!",
  ui_story_31550601_109_dialog_content = "Aku masih terlihat sangat gugup...",
  ui_story_31550601_110_dialog_content = "Heheh, dan aku masih fotogenik seperti biasanya!",
  ui_story_31550601_111_dialog_content = "...",
  ui_story_31550601_112_dialog_content = "Aku ingat pernah mengambil foto seperti ini sebelumnya...",
  ui_story_31550601_113_dialog_content = "Ah! Benar... Foto grup lama kita...",
  ui_story_31550601_114_dialog_content = "Baiklah, sekarang setiap orang tersenyum lebar kali ini—Jayalah Illumina!",
  ui_story_31550601_115_dialog_content = "<size=45>Splendor Illumina!</size>",
  ui_story_31550601_116_dialog_content = "Anak-anak dari Legiun ke-2...",
  ui_story_31550601_117_dialog_content = "Apakah kamu telah menjadi bintang yang menerangi jalan orang lain?"
}
return config
